<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Support\Database;
$fixtures=[];$competitions=[];
try{$pdo=Database::connection();$fixtures=$pdo->query("SELECT f.provider_id,f.kickoff,f.status,f.home_score,f.away_score,f.stats_imported,c.name competition_name,c.country_name,c.logo competition_logo,h.name home_name,h.logo home_logo,a.name away_name,a.logo away_logo FROM fixtures f JOIN competitions c ON c.id=f.competition_id JOIN teams h ON h.id=f.home_team_id JOIN teams a ON a.id=f.away_team_id WHERE c.prediction_enabled=1 AND f.kickoff>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY) ORDER BY f.kickoff ASC LIMIT 40")->fetchAll(PDO::FETCH_ASSOC);$competitions=$pdo->query("SELECT name,country_name,logo FROM competitions WHERE prediction_enabled=1 ORDER BY FIELD(country_name,'England','Spain','Italy','Germany','France','Europe') DESC,country_name,name LIMIT 12")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function dt(string $v,string $f):string{try{$d=new DateTime($v,new DateTimeZone('UTC'));$d->setTimezone(new DateTimeZone('Europe/Berlin'));return $d->format($f);}catch(Throwable){return '—';}}function initials(string $v):string{$p=preg_split('/\s+/',trim($v));return strtoupper(substr($p[0]??'',0,1).substr($p[1]??'',0,1));}
$groups=[];foreach($fixtures as $f)$groups[$f['competition_name']][]=$f;$activePage='matches';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TukiScore — Football Intelligence</title><meta name="description" content="Football predictions, probabilities, match statistics and model intelligence."><link rel="stylesheet" href="assets/app.css"></head><body><?php require __DIR__.'/partials/header.php';?><div class="shell"><div class="layout"><aside class="leftbar"><div class="sidebar-title">COMPETITIONS WE COVER</div><div class="card league-list"><div class="league-head">⚽ &nbsp; Football</div><?php foreach($competitions as $c):?><a class="league-link" href="#<?=e(preg_replace('/[^a-z0-9]+/i','-',strtolower($c['name'])))?>"><span class="league-logo"><?php if($c['logo']):?><img src="<?=e($c['logo'])?>"><?php else:?><?=e(initials($c['name']))?><?php endif;?></span><span style="min-width:0"><div class="league-name"><?=e($c['name'])?></div><div class="league-country"><?=e($c['country_name']?:'International')?></div></span></a><?php endforeach;?></div></aside><main style="min-width:0"><section class="card"><div class="panel-head"><div><div class="section-label">MATCH CENTRE</div><h1 style="margin-top:4px">Today's Matches</h1><div class="subtext">Fixtures, results and intelligence from the competitions we cover.</div></div><div class="segmented"><button class="active">All matches</button><button>Live</button><button>Upcoming</button></div></div><div class="datebar"><?php foreach([-2,-1,0,1,2] as $o):$d=(new DateTimeImmutable('today'))->modify(($o>=0?'+':'').$o.' day');?><div class="date-pill <?=$o===0?'active':''?>"><strong><?=$o===0?'TODAY':strtoupper($d->format('D'))?></strong><span><?=$d->format('d M')?></span></div><?php endforeach;?></div><?php if(!$groups):?><div class="empty"><strong style="display:block;color:#17191c;font-size:16px;margin-bottom:7px">No fixtures available yet</strong>The collector is preparing supported competition data.</div><?php else:?><?php foreach($groups as $competition=>$matches):?><section id="<?=e(preg_replace('/[^a-z0-9]+/i','-',strtolower($competition)))?>"><div class="competition-head"><strong><?=e($competition)?></strong><span><?=count($matches)?> matches</span></div><?php foreach($matches as $f):?><a class="match-row" href="match.php?id=<?=urlencode($f['provider_id'])?>"><div class="match-time"><?=e(dt($f['kickoff'],'H:i'))?><div class="match-date"><?=e(dt($f['kickoff'],'d M'))?></div></div><div><div class="team-line"><span class="team-logo"><?php if($f['home_logo']):?><img src="<?=e($f['home_logo'])?>"><?php else:?><?=e(initials($f['home_name']))?><?php endif;?></span><?=e($f['home_name'])?></div><div class="team-line"><span class="team-logo"><?php if($f['away_logo']):?><img src="<?=e($f['away_logo'])?>"><?php else:?><?=e(initials($f['away_name']))?><?php endif;?></span><?=e($f['away_name'])?></div></div><div class="score"><?=$f['home_score']!==null?e($f['home_score'].' : '.$f['away_score']):'—'?></div><span class="badge <?=$f['stats_imported']?'ready':''?>"><?=$f['stats_imported']?'DATA READY':'PREVIEW'?></span></a><?php endforeach;?></section><?php endforeach;?><?php endif;?></section></main><aside class="rightbar"><div class="card side-info"><h3>TukiScore Intelligence</h3><div class="subtext">Model status</div><div class="status-box"><div class="status-title">● DATA ENGINE ACTIVE</div><div class="status-copy">Historical data is being collected and validated before forecasts are published.</div></div><?php foreach([['Result model','Preparing'],['Goals model','Preparing'],['Shots model','Queued'],['Corners model','Queued']] as $m):?><div class="model-line"><span><?=$m[0]?></span><span><?=$m[1]?></span></div><?php endforeach;?><a class="button-dark" href="performance.php">View model performance</a></div><div class="card side-info" style="margin-top:14px"><h3>Popular markets</h3><?php foreach(['Match result (1X2)','Both teams to score','Over / Under goals','Double chance','Correct score'] as $m):?><div class="model-line"><span><?=$m?></span><span>›</span></div><?php endforeach;?></div></aside></div><footer class="footer"><span>© <?=date('Y')?> TukiScore</span><span>Probabilities are estimates, not guarantees.</span></footer></div></body></html>